/* CFO comments — 2026-10-25. Scoped to the WordPress reply form. */
.single-post #respond.comment-respond {
  box-sizing: border-box;
  max-width: 780px;
  margin: 16px auto 48px;
  padding: clamp(20px, 4vw, 40px);
  border: 1px solid #e6dcd2;
  border-top: 3px solid #a33228;
  background: #fbf6f0;
  color: #193f4d;
  font-family: "Source Sans 3", sans-serif;
}
.single-post #respond *, .single-post #respond *::before,
.single-post #respond *::after { box-sizing: border-box; }
.single-post #respond .comment-reply-title {
  margin: 0 0 16px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: clamp(28px, 4vw, 36px);
  font-weight: 700;
  line-height: 1.15;
}
.single-post #respond .comment-reply-title small {
  display: block; margin-top: 8px; font: 400 15px/1.5 "Source Sans 3", sans-serif;
}
.single-post #respond .comment-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 20px 24px;
}
.single-post #respond .comment-form > p { min-width: 0; margin: 0; }
.single-post #respond .comment-form > p:not(.comment-form-author):not(.comment-form-email) {
  grid-column: 1 / -1;
}
.single-post #respond .comment-notes,
.single-post #respond .logged-in-as {
  color: #586d74; font-size: 15px; line-height: 1.6;
}
.single-post #respond .comment-form label {
  display: block;
  margin-bottom: 7px;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.5;
}
.single-post #respond .required { color: #a33228; }
.single-post #respond .comment-form textarea,
.single-post #respond .comment-form input[type="text"],
.single-post #respond .comment-form input[type="email"],
.single-post #respond .comment-form input[type="url"] {
  display: block;
  width: 100%;
  max-width: 100%;
  min-height: 48px;
  margin: 0;
  padding: 12px 14px;
  border: 1px solid #a8b6ba;
  border-radius: 3px;
  background: #fff;
  color: #193f4d;
  font: 400 17px/1.5 "Source Sans 3", sans-serif;
  box-shadow: none;
}
.single-post #respond .comment-form textarea {
  min-height: 180px;
  resize: vertical;
}
.single-post #respond .comment-form textarea:focus-visible,
.single-post #respond .comment-form input:focus-visible,
.single-post #respond a:focus-visible {
  outline: 3px solid #193f4d;
  outline-offset: 3px;
}
.single-post #respond .comment-form .comment-form-cookies-consent {
  display: flex; align-items: flex-start; gap: 10px;
}
.single-post #respond .comment-form-cookies-consent input[type="checkbox"] {
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  min-height: 20px;
  margin: 3px 0 0;
  accent-color: #a33228;
}
.single-post #respond .comment-form .comment-form-cookies-consent label {
  margin: 0;
  color: #586d74;
  font-size: 15px;
  font-weight: 400;
}
.single-post #respond .form-submit input[type="submit"] {
  display: inline-block;
  width: auto;
  max-width: 100%;
  min-height: 48px;
  padding: 12px 22px;
  border: 2px solid #a33228;
  border-radius: 3px;
  background: #a33228;
  color: #fff;
  font: 700 17px/1.4 "Source Sans 3", sans-serif;
  white-space: normal;
  cursor: pointer;
}
.single-post #respond .form-submit input[type="submit"]:hover {
  border-color: #7f281f; background: #7f281f;
}
.single-post #respond a { color: #8d2e25; text-underline-offset: 3px; }
@media (max-width: 600px) {
  .single-post #respond .comment-form { grid-template-columns: minmax(0, 1fr); }
  .single-post #respond .comment-form > p { grid-column: 1; }
  .single-post #respond .form-submit input[type="submit"] { width: 100%; }
}
